from common_e15 import *
import numpy as np,pandas as pd

def main():
 deadline=time.monotonic()+7200
 while not (R/'FINAL_R8E15_DECISION.md').exists():
  if (R/'21_reproducibility/CLOSEOUT_STOP.json').exists():raise RuntimeError('closeout stopped')
  assert time.monotonic()<deadline;time.sleep(10)
 assert read(R/'18_independent_verification/INDEPENDENT_PASS.json')['passed'];out=[];maxerr=0.;n=0
 for a in rows(R/'SOURCE_LEVEL_FIELD_METRICS.csv'):
  p=dict(np.load(a['path']));sid=a['source_id'];g=dict(np.load(R/'02_source_geometry'/sid/'ADJACENCY.npz'));ij=g['pairs'];horizontal=g['x_axis_edge'];cross=(g['tile_id'][ij[:,0]]!=g['tile_id'][ij[:,1]])&horizontal if a['condition']!='FULL' else np.zeros(len(ij),bool);dp=p['pred_MPa'][ij[:,1]]-p['pred_MPa'][ij[:,0]];dy=p['reference_MPa'][ij[:,1]]-p['reference_MPa'][ij[:,0]];name='_'.join(a[k] for k in ['model','fold','seed','source_id','condition','policy']);saved=dict(np.load(R/'12_tile_boundary_analysis'/(name+'_ALL_EDGE_JUMPS.npz')));assert np.array_equal(dp,saved['delta_prediction_MPa']) and np.array_equal(dy,saved['delta_reference_MPa']);assert np.array_equal(abs(dp)-abs(dy),saved['signed_excess_MPa']);assert np.array_equal(abs(dp-dy),saved['absolute_jump_error_MPa']);n+=1
  for label,values in [('absolute_prediction_jump',abs(dp)),('absolute_jump_error',abs(dp-dy))]:
   vals=np.sort(values[horizontal]);pos=.95*(len(vals)-1);lo=int(np.floor(pos));hi=int(np.ceil(pos));threshold=float(vals[lo]+(vals[hi]-vals[lo])*(pos-lo));err=abs(threshold-float(np.quantile(values[horizontal],.95)));maxerr=max(maxerr,err);assert err<1e-10;tail=horizontal&(values>=threshold);base=float(cross.sum()/horizontal.sum());tailfraction=float(np.sum(tail&cross)/tail.sum());out.append(dict(**{k:a[k] for k in ['model','seed','source_id','plate','condition','policy']},tail_metric=label,threshold_Q95_MPa=threshold,horizontal_edges=int(horizontal.sum()),actual_boundary_edges=int(cross.sum()),tail_edges=int(tail.sum()),actual_boundary_tail_edges=int(np.sum(tail&cross)),baseline_actual_boundary_fraction=base,tail_actual_boundary_fraction=tailfraction,boundary_tail_enrichment_ratio=tailfraction/base if base>0 else None,FULL_no_original_seams=a['condition']=='FULL',threshold_definition='linear unweighted edge quantile95, >= inclusion; evaluation-only'))
 table(R/'12_tile_boundary_analysis/BOUNDARY_TAIL_ENRICHMENT.csv',out);df=pd.DataFrame(out);macro=df[df.condition!='FULL'].groupby(['model','seed','condition','policy','tail_metric','plate'])[['boundary_tail_enrichment_ratio','tail_actual_boundary_fraction','baseline_actual_boundary_fraction']].mean().groupby(['model','condition','policy','tail_metric']).mean(numeric_only=True).reset_index().drop(columns=['seed'],errors='ignore');table(R/'12_tile_boundary_analysis/TAIL_ENRICHMENT_MACROS.csv',macro.to_dict('records'))
 from reports_e15 import md
 text='\n\n## Largest-jump concentration audit\n\nAll728 complete saved T0-edge jump distributions were independently reconstructed from source-indexed evaluated predictions and unchanged references. For each field, the largest5% of horizontal-edge absolute prediction jumps and absolute jump errors were defined by a linear edge-count95th percentile with >= inclusion. Actual boundary-tail membership is compared with the fraction of all horizontal edges that cross a real original boundary. FULL has zero original seam edges and its enrichment is null. Enrichment above1 indicates concentration relative to boundary frequency; it does not imply that most extreme jumps are seams, that every seam is artificial, or that boundary association proves a sole cause. The two tail definitions are retained separately in the source-level CSV.\n\nThe following macros retain the two tail definitions separately, with source means within plates, five equal plates and both seed metrics. See the separate definitions in the full CSV for exact tail attribution.\n\n'+md(macro[macro.policy.isin(['S0','S1','S2'])])
 for name in ['R8E15_MASTER_REPORT.md','TILE_BOUNDARY_DISCONTINUITY.md','BOUNDARY_VS_INTERIOR_JUMP_ANALYSIS.md']:
  path=R/name;path.write_text(path.read_text(encoding='utf8')+text,encoding='utf8')
 write(R/'18_independent_verification/TAIL_AUDIT_PASS.json',dict(UTC=now(),passed=True,all_edge_vector_fields=n,independent_Q95_checks=len(out),maximum_threshold_difference=maxerr,actual_FULL_seams=0));print('TAIL_AUDIT_PASS',n,len(out),maxerr,flush=True)
if __name__=='__main__':main()
